import{_ as o,l,o as e,c as n,v as t,p as d,x as i,d as s,i as h,S as D}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"3D NAND 与光刻负担转移","description":"","frontmatter":{"title":"3D NAND 与光刻负担转移","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/3d-nand-litho-shift.md","filePath":"litho/3d-nand-litho-shift.md","lastUpdated":1789023840000}'),p={name:"litho/3d-nand-litho-shift.md"};function A(c,a,E,N,_,m){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="_3d-nand-与光刻负担转移" tabindex="-1">3D NAND 与光刻负担转移 <a class="header-anchor" href="#_3d-nand-与光刻负担转移" aria-label="Permalink to &quot;3D NAND 与光刻负担转移&quot;">​</a></h1><div class="epigraph"><p>加层比缩孔更划算的阶段，扫描机从分辨率机器变成对准与大深宽比集成的仆人。</p><footer>—— 对照 3D NAND 堆叠使图形化瓶颈从光刻转向刻蚀/沉积的公开产业叙事</footer></div><p><a href="/litho/memory-litho-dram-nand">上一课</a>区分 DRAM 与 NAND。缺口是转移机制。本课钉 3D NAND 与光刻负担转移。替代光刻形态从<a href="/litho/multibeam-direct-write">下一课</a> 另起课序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>沟道孔要穿过百层介质，ARDE、扭曲、选择比是主墙；光刻提供孔位置、CD 均值与倾斜预算。台阶（staircase）要多次曝光或特殊光刻定义每层接触。键合两片 NAND 时对准进封装光刻量级或更好。EUV 对孔的随机与成本交叉仍可能出现，但「每两年加层」阶段的 capex 偏向刻蚀机台。</p><p>缺口是<strong>边际回报从 k1 转到层数</strong>，不是 NAND 无光刻。把 3D NAND 当光学课的反例即可：同一门课程序列里，瓶颈可以离开投影光学。</p><h3 id="与逻辑-3d-cfet-不同" tabindex="-1">与逻辑 3D（CFET）不同 <a class="header-anchor" href="#与逻辑-3d-cfet-不同" aria-label="Permalink to &quot;与逻辑 3D（CFET）不同&quot;">​</a></h3><p>逻辑 3D 仍要密金属与切线；NAND 的重复孔阵列对 SMO 二维自由度需求不同。不要把负担转移写成所有 3D 的普遍定律。</p><p><span class="marginnote">孔倾斜与套刻在电学上变成串扰与开路。光刻规格以电学为源，规则起源课的逻辑在此同样适用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预算：孔 CD、位置、倾斜、台阶套刻。机台组合：浸没或 KrF 对某些非最密层可能足够。检测：深孔需要特殊计量，e-beam/光学对表面，剖面靠 FA。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>比特密度 ≈ 层数 × 孔面密度。层数增加时，刻蚀时间与难度涨；孔节距缩时，光刻与随机涨。产业选择了先加层，于是光刻相对份额下降。层数墙出现后，节距与 EUV 可能再回来——IRDS 存储章的红格，不是本课预言。</p>',13)),(e(),d(D,null,{default:i(()=>[h(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAYERS%5B%22%E5%8A%A0%E5%B1%82%22%5D%20--%3E%20ETCH%5B%22%E5%88%BB%E8%9A%80%20%2F%20%E6%B2%89%E7%A7%AF%E5%A2%99%22%5D%0A%20%20PITCH%5B%22%E7%BC%A9%E5%AD%94%E8%8A%82%E8%B7%9D%22%5D%20--%3E%20LITH%5B%22%E5%85%89%E5%88%BB%20%2F%20%E9%9A%8F%E6%9C%BA%E5%A2%99%22%5D%0A%20%20HIST%5B%22%E8%BF%91%E5%8D%81%E5%B9%B4%E9%80%89%E6%8B%A9%22%5D%20--%3E%20ETCH%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不预测何时缩孔再成主墙。不给堆叠层数表。节点经济课序在 NAND 转移处收束，下一课序谈投影光刻的替代形态。</p><p>后课默认：并非一切先进图形化都是 EUV 逻辑；下一课多束直写作为另一条「不经过掩模」的路。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>3D NAND 阶段边际密度常来自加层，瓶颈在深孔刻蚀。</li><li>光刻仍管孔位、台阶、键合对准。</li><li>与逻辑 3D 的负担结构不同。</li><li>出处：3D NAND 图形化负担转移的公开产业叙事。</li></ul>',5))])}const T=o(p,[["render",A]]);export{u as __pageData,T as default};
